function validate([apples, days]) {
  if (!Array.isArray(apples) || !Array.isArray(days) || apples.length !== days.length) return 'apples and days must have the same length.';
  if (apples.length < 1 || apples.length > 20000) return 'There are 1 to 2 * 10^4 days.';
  for (let i = 0; i < apples.length; i++) {
    const a = apples[i], d = days[i];
    if (!Number.isInteger(a) || !Number.isInteger(d) || a < 0 || d < 0 || a > 20000 || d > 20000) return 'Each value is an integer from 0 to 2 * 10^4.';
    if ((a === 0) !== (d === 0)) return 'days[i] is 0 exactly when apples[i] is 0.';
  }
  return null;
}

