function eatenApples(apples, days) {
  const heap = [];
  const push = (item) => {
    heap.push(item);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent][0] <= heap[child][0]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  };
  const pop = () => {
    const last = heap.pop();
    if (heap.length === 0) return;
    heap[0] = last;
    let parent = 0;
    for (;;) {
      const left = 2 * parent + 1;
      const right = left + 1;
      let smallest = parent;
      if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
      if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
      if (smallest === parent) break;
      [heap[parent], heap[smallest]] = [heap[smallest], heap[parent]];
      parent = smallest;
    }
  };

  let eaten = 0;
  for (let day = 0; day < apples.length || heap.length > 0; day++) {
    if (day < apples.length && apples[day] > 0) {
      push([day + days[day], apples[day]]);
    }
    while (heap.length > 0 && heap[0][0] <= day) {
      pop();
    }
    if (heap.length > 0) {
      heap[0][1]--;
      eaten++;
      if (heap[0][1] === 0) {
        pop();
      }
    }
  }
  return eaten;
}

