function eatenApples(apples, days) {
  // Maximum matching between single apples and eating days (Kuhn's augmenting paths).
  const windows = [];
  for (let i = 0; i < apples.length; i++) {
    for (let k = 0; k < apples[i]; k++) windows.push([i, i + days[i] - 1]);
  }
  const owner = new Map();
  const assign = (a, visited) => {
    for (let d = windows[a][0]; d <= windows[a][1]; d++) {
      if (visited.has(d)) continue;
      visited.add(d);
      if (!owner.has(d) || assign(owner.get(d), visited)) {
        owner.set(d, a);
        return true;
      }
    }
    return false;
  };
  let count = 0;
  for (let a = 0; a < windows.length; a++) if (assign(a, new Set())) count++;
  return count;
}

