function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 7);
  const maxApples = large ? (rand() < 0.5 ? 20000 : 5) : 1 + Math.floor(rand() * 5);
  const maxDays = large ? (rand() < 0.5 ? 20000 : 8) : 1 + Math.floor(rand() * 6);
  const emptyChance = rand() * 0.6;
  const apples = [];
  const days = [];
  for (let i = 0; i < n; i++) {
    if (rand() < emptyChance) {
      apples.push(0);
      days.push(0);
    } else {
      apples.push(1 + Math.floor(rand() * maxApples));
      days.push(1 + Math.floor(rand() * maxDays));
    }
  }
  return [apples, days];
}
